def try_fix(s):
    if not s:
        return s, "none"
    # try latin1 -> utf8
    candidates = []
    try:
        b = s.encode("latin1")
        for enc in ["utf-8", "cp932", "euc_jp", "shift_jis"]:
            try:
                fixed = b.decode(enc)
                candidates.append((enc, fixed))
            except Exception:
                pass
    except Exception:
        pass
    return candidates

